package plcnext

// tags.go renders the tag file a project composes for a manifest's
// bindings — `naut plcnext tags`.

import (
	"fmt"

	"github.com/joyautomation/nautilus/internal/tagfile"
)

// TagsYAML renders the tag file: inputs for dir in, outputs for dir out,
// with the binding's unit, desc and init. Desc falls back to the module
// the offset falls in, so a generated file still says what a tag is.
func TagsYAML(m Manifest, tagsPath string) ([]byte, error) {
	header := []string{
		"Generated by `naut plcnext tags plcnext_manifest.yaml` — one tag per",
		"binding in the manifest. Do not edit — re-run after changing the manifest.",
		"",
		fmt.Sprintf("Compose it into a project with:  tag-files: [%s]", tagsPath),
	}
	var tags []tagfile.Tag
	for _, b := range m.Tags {
		t := tagfile.Tag{Name: b.Name, Role: "input", Unit: b.Unit, Desc: b.Desc}
		if b.Dir == DirOut {
			t.Role = "output"
			t.Init = b.Init
			if t.Init == nil {
				if b.format().Digital() {
					t.Init = false
				} else {
					t.Init = 0.0
				}
			}
		}
		if t.Desc == "" {
			t.Desc = m.describe(b)
		}
		tags = append(tags, t)
	}
	return tagfile.Render(header, tags)
}
